mapper.sql:
WHERE deliveries.status > 0

    AND (
    deliveries.code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR deliveries.note LIKE CONCAT('%', #{filter.searchText}, '%')
    OR EXISTS (
    SELECT 1 FROM sales_orders so
    INNER JOIN customers c ON c.id = so.customer_id
    WHERE so.delivery_id = deliveries.id
    AND so.status > 0
    AND c.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )
    OR EXISTS (
    SELECT 1 FROM sales_orders so
    WHERE so.delivery_id = deliveries.id
    AND so.status > 0
    AND so.so_code LIKE CONCAT('%', #{filter.searchText}, '%')
    )
    )


    AND deliveries.date >= #{filter.dateFrom}


    AND deliveries.date <= #{filter.dateTo}


    AND deliveries.status = #{filter.status}


    AND deliveries.created_by = #{filter.createdBy}


    AND sales_orders.company_id = #{filter.companyId}


    AND sales_orders.location_group_id = #{filter.warehouseId}


    AND sales_orders.customer_id = #{filter.organizationId}


    AND sales_orders.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})

mapper.select:
SELECT deliveries.id AS id, deliveries.code AS dnCode, deliveries.date AS dnDate, GROUP_CONCAT(DISTINCT cgroups.name SEPARATOR ', ') AS organizationGroupName, MAX(customers.name) AS organizationName, GROUP_CONCAT(DISTINCT sales_orders.so_code SEPARATOR ', ') AS invoiceCode, deliveries.created AS created, deliveries.status AS status FROM deliveries LEFT JOIN sales_orders ON sales_orders.delivery_id = deliveries.id AND sales_orders.status > 0 LEFT JOIN customers ON customers.id = sales_orders.customer_id LEFT JOIN customer_cgroups ON customer_cgroups.customer_id = sales_orders.customer_id LEFT JOIN cgroups ON cgroups.id = customer_cgroups.cgroup_id
GROUP BY deliveries.id
LIMIT #{filter.page}, #{filter.rowsPerPage}
